          answer: 0,
          explain: '\u865A\u8BC1\u7684\u6838\u5FC3\u662F"\u4E0D\u8DB3"\uFF1A\u4E4F\u529B\u3001\u6C14\u77ED\u3001\u9762\u8272\u6DE1\u767D\u3001\u6613\u7D2F\u3001\u8109\u65E0\u529B\u3002\u5B9E\u8BC1\u7684\u6838\u5FC3\u662F"\u6709\u4F59"\uFF1A\u58F0\u9AD8\u6C14\u7C97\u3001\u80C0\u6EE1\u62D2\u6309\u3001\u4FBF\u5E72\u5C3F\u9EC4\u3002\u540C\u6837\u7684"\u7D2F"\uFF0C\u865A\u4E0E\u5B9E\u6027\u8D28\u5B8C\u5168\u4E0D\u540C\u3002',
          insight: '\u5224\u65AD\u865A\u5B9E\u7684\u5173\u952E\u4E0D\u662F\u75C7\u72B6\u672C\u8EAB\uFF0C\u800C\u662F"\u8EAB\u4F53\u662F\u7F3A\u4E86\u4E1C\u897F\uFF0C\u8FD8\u662F\u591A\u4E86\u4E1C\u897F"\u3002\u7F3A\u4E86\u8981\u8865\uFF0C\u591A\u4E86\u8981\u6E05\u2014\u2014\u5F04\u53CD\u4E86\u4F1A\u8D8A\u6CBB\u8D8A\u7CDF\u3002'
