          explain: '\u4E94\u884C\u4E2D\u809D\u5C5E\u6728\u3001\u813E\u5C5E\u571F\uFF0C\u6728\u514B\u571F\u3002\u809D\u6C14\u8FC7\u65FA\u6216\u90C1\u7ED3\uFF0C\u4F1A"\u4E58"\u813E\u571F\uFF0C\u5BFC\u81F4\u80C3\u80C0\u3001\u7EB3\u5DEE\u3001\u8179\u6CFB\u3002\u6240\u4EE5\u6CBB\u80C3\u75C5\u5E38\u8981"\u758F\u809D"\uFF0C\u8FD9\u5C31\u662F\u6574\u4F53\u89C2\u3002',
