            answer: 1,
            explain: "\u809D\u6728\u4E58\u813E\u571F\uFF1A\u809D\u6C14\u8FC7\u65FA\u5F71\u54CD\u813E\u80C3\u8FD0\u5316\uFF0C\u51FA\u73B0\u80C3\u80C0\u3001\u7EB3\u5DEE\u3001\u8179\u6CFB\uFF0C\u6CBB\u7597\u9700\u758F\u809D\u5065\u813E\u517C\u987E\u3002"
