          teachingPoint: '\u7406\u89E3"\u4E3B\u52A8\u6536\u96C6\u7EBF\u7D22"\u7684\u4EF7\u503C\uFF1A\u4E00\u4E2A\u597D\u95EE\u9898\u80FD\u628A\u4E0D\u786E\u5B9A\u53D8\u6210\u786E\u5B9A\u3002',
          safetyNote: "\u95EE\u8BCA\u4FE1\u606F\u4EC5\u4F9B\u53C2\u8003\uFF0C\u8BCA\u65AD\u8BF7\u7531\u4E13\u4E1A\u533B\u5E08\u5B8C\u6210\u3002"
