          sourceType: "classic",
          originalText: "\u5584\u8BCA\u8005\uFF0C\u5BDF\u8272\u6309\u8109\uFF0C\u5148\u522B\u9634\u9633\u3002",
          modernExplanation: "\u300A\u7D20\u95EE\xB7\u9634\u9633\u5E94\u8C61\u5927\u8BBA\u300B\u8BF4\uFF1A\u5584\u4E8E\u8BCA\u75C5\u7684\u4EBA\uFF0C\u89C2\u5BDF\u9762\u8272\u3001\u89E6\u6478\u8109\u8C61\uFF0C\u9996\u5148\u5206\u8FA8\u9634\u9633\uFF0C\u518D\u7EFC\u5408\u5224\u65AD\u2014\u2014\u8109\u8BCA\u4ECE\u5C5E\u4E8E\u6574\u4F53\u8BCA\u65AD\u3002",
          teachingPoint: '\u5EFA\u7ACB"\u4EFB\u4F55\u5355\u4E00\u4FE1\u606F\u90FD\u4E0D\u8DB3\u4EE5\u5B9A\u8BBA"\u7684\u7EAA\u5F8B\uFF0C\u7406\u89E3\u56DB\u8BCA\u5408\u53C2\u3002',
