          { id: "e", text: "\u5979\u611F\u89C9\u81EA\u5DF1\u597D\u591A\u4E86", isObservation: false },
          { id: "f", text: "\u5979\u5E94\u8BE5\u5FEB\u597D\u4E86", isObservation: false },
          { id: "g", text: "\u5979\u70E7\u9000\u4E86\u5C31\u6CA1\u5927\u788D\u4E86", isObservation: false }
