              { id: "b", text: "\u813E\u865A\uFF0C\u5403\u53C2\u82D3\u767D\u672F\u4E38\u8865\u4E00\u8865", correct: false, why: '\u5927\u4FBF\u81ED\u79FD\u3001\u809B\u95E8\u707C\u70ED\u662F"\u70ED"\u7684\u8BC1\u636E\uFF0C\u8FD9\u65F6\u5019\u8865\u813E\u7B49\u4E8E\u628A\u6E7F\u70ED\u5173\u5728\u809A\u5B50\u91CC\uFF0C\u8D8A\u8865\u8D8A\u80C0\u3002' },
              { id: "c", text: "\u5BD2\u6E7F\u8179\u6CFB\uFF0C\u9700\u8981\u6E29\u4E2D\u6563\u5BD2", correct: false, why: "\u5BD2\u6E7F\u8179\u6CFB\u591A\u6E05\u7A00\u4E0D\u81ED\u3001\u5F97\u6E29\u5219\u51CF\uFF0C\u5C0F\u5B8B\u662F\u81ED\u79FD\u707C\u70ED\uFF0C\u65B9\u5411\u6B63\u597D\u76F8\u53CD\u3002" }
